import type { RamayanaBeginningPlayableScene } from "./ramayana-beginnings-playable";

export const RAMAYANA_RAINS_AND_DELAY_PLAYABLE_SCENES: RamayanaBeginningPlayableScene[] = [
  { id: "prasravana-becomes-the-rain-shelter", nodeIds: ["rama", "lakshmana", "sita", "sugriva", "prasravana", "kishkindha"], moment: { id: "prasravana-becomes-the-rain-shelter", decisiveChange: { en: "A safe cave gives Rama shelter but not rest; Lakshmana helps him make waiting an intentional part of the rescue.", hi: "सुरक्षित गुफा राम को आश्रय देती है, विश्राम नहीं; लक्ष्मण प्रतीक्षा को बचाव की सोची-समझी तैयारी बनाने में उनका साथ देते हैं।" }, beats: [
    { id: "the-brothers-choose-prasravana", title: { en: "A cave becomes the monsoon base", hi: "एक गुफा मानसून का पड़ाव बनती है" }, narration: { en: "Rama and Lakshmana inspect Prasravana and choose a broad cave protected from wind and rain. A stream, flowering slopes, level stone and sightlines toward Kishkindha make it both shelter and watch-post. They can hear traces of the restored city without entering it, close enough for alliance and far enough to keep Rama's exile vow.", hi: "राम और लक्ष्मण प्रस्रवण को देखकर ऐसी चौड़ी गुफा चुनते हैं जो हवा और वर्षा से बचाती है। धारा, फूलों वाली ढलान, समतल शिला और किष्किंधा की ओर खुला दृश्य इसे आश्रय के साथ चौकी भी बनाते हैं। वे नगर में गए बिना उसकी ध्वनियाँ सुन सकते हैं—मित्रता के लिए पास और राम के वनवास-वचन के लिए पर्याप्त दूर।" }, visualCue: "Open on rain sweeping across layered mountain depth; the cave, stream, and distant warm lights of Kishkindha remain simultaneously navigable landmarks.", characterIds: ["rama", "lakshmana", "sugriva"] },
    { id: "safety-does-not-bring-sleep", title: { en: "The night is dry, but Rama cannot sleep", hi: "रात सूखी है, पर राम सो नहीं पाते" }, narration: { en: "Inside the protected cave, Rama remains awake. Sugriva has recovered his wife and kingdom, while Sita's whereabouts are still unknown; the contrast makes silence painful. Rama's mind keeps returning to her captivity, and the comfort of the shelter exposes rather than cures his helplessness during the closed season.", hi: "सुरक्षित गुफा के भीतर भी राम जागते रहते हैं। सुग्रीव को पत्नी और राज्य वापस मिल चुके हैं, जबकि सीता कहाँ हैं यह अब भी अज्ञात है; यह अंतर मौन को पीड़ादायक बना देता है। उनका मन बार-बार सीता की कैद पर लौटता है और आश्रय का आराम बंद ऋतु में उनकी असहायता मिटाने के बजाय उजागर करता है।" }, visualCue: "Let the cave fire dim while a distant, unreachable Sita marker pulses beyond storm clouds; sleep never activates despite physical safety.", characterIds: ["rama", "sita", "sugriva", "lakshmana"] },
    { id: "lakshmana-keeps-grief-from-stopping-action", title: { en: "Lakshmana refuses to let sorrow become surrender", hi: "लक्ष्मण शोक को हार नहीं बनने देते" }, narration: { en: "Lakshmana does not dismiss Rama's pain. He reminds him that endurance, energy and clear purpose are needed if Sita is to be found, and that grief without direction can consume the strength required for action. His companionship changes the night from solitary despair into a shared watch over an unfinished promise.", hi: "लक्ष्मण राम की पीड़ा को छोटा नहीं करते। वे याद दिलाते हैं कि सीता की खोज के लिए धैर्य, ऊर्जा और स्पष्ट उद्देश्य चाहिए, और दिशाहीन शोक उसी शक्ति को खा सकता है जिसकी आगे आवश्यकता होगी। उनका साथ उस रात को अकेली निराशा से बदलकर अधूरे वचन पर दो भाइयों की साझा पहरेदारी बना देता है।" }, visualCue: "Lakshmana moves beside Rama rather than in front of him; two linked silhouettes face the same storm and the same obscured rescue route.", characterIds: ["lakshmana", "rama", "sita"] },
    { id: "waiting-becomes-a-seasonal-decision", title: { en: "Patience is chosen, not imposed", hi: "धैर्य चुना जाता है, थोपा नहीं" }, narration: { en: "Rama agrees that the flooded season must be endured and says a worthy friend returns help when the proper moment comes. He chooses not to suspect Sugriva while roads are unusable. The brothers therefore hold position, preserve strength and attach their next movement to autumn instead of pretending that urgency can defeat terrain.", hi: "राम मानते हैं कि बाढ़ वाली ऋतु सहनी होगी और कहते हैं कि योग्य मित्र उचित समय आने पर उपकार लौटाता है। जब मार्ग अनुपयोगी हैं तब वे सुग्रीव पर संदेह न करने का निर्णय लेते हैं। दोनों भाई वहीं रहकर शक्ति बचाते और अगली चाल को शरद से जोड़ते हैं; वे यह दिखावा नहीं करते कि केवल उतावली भूगोल को हरा सकती है।" }, visualCue: "A seasonal dial locks outbound paths in rain while an autumn waypoint remains visible, converting an apparent pause into an explicit future move.", characterIds: ["rama", "lakshmana", "sugriva", "sita"] },
  ] } },

  { id: "monsoon-closes-every-road", nodeIds: ["rama", "lakshmana", "sita", "sugriva", "prasravana", "rain-forest"], moment: { id: "monsoon-closes-every-road", decisiveChange: { en: "The rain makes movement impossible and memory unavoidable, yet Rama keeps trust with Sugriva until the season changes.", hi: "वर्षा चलना असंभव और स्मृति से बचना कठिन कर देती है, फिर भी ऋतु बदलने तक राम सुग्रीव पर भरोसा रखते हैं।" }, beats: [
    { id: "sky-earth-and-rivers-change-shape", title: { en: "The land stops behaving like a road", hi: "धरती मार्ग की तरह काम करना छोड़ देती है" }, narration: { en: "Clouds erase the horizon, rivers burst their banks, slopes shed mud and tracks disappear under water. Animals seek cover while armies and merchants halt. What looks beautiful from the cave is dangerous at ground level: a rescue party could neither hold direction nor cross the swollen barriers with reliable speed.", hi: "बादल क्षितिज मिटा देते हैं, नदियाँ किनारे तोड़ती हैं, ढलानों से कीचड़ बहता है और पगडंडियाँ पानी में खो जाती हैं। पशु आश्रय लेते हैं, सेनाएँ और व्यापारी रुकते हैं। गुफा से सुंदर दिखने वाला दृश्य धरातल पर खतरनाक है—खोज-दल दिशा नहीं पकड़ सकता और उफनती बाधाएँ भरोसेमंद गति से पार नहीं कर सकता।" }, visualCue: "Animate familiar paths being submerged one after another; attempted route lines bend, break, and disappear beneath rising water rather than merely fading.", characterIds: ["rama", "lakshmana"] },
    { id: "every-weather-sign-recalls-sita", title: { en: "The monsoon keeps turning into Sita", hi: "मानसून बार-बार सीता की स्मृति बन जाता है" }, narration: { en: "Lightning, frightened birds, rain-dark earth and separated pairs all call Sita back into Rama's thoughts. He imagines how she may hear the same storms in captivity and whether fear has deepened her suffering. Nature is not decoration around his grief; each changing sign becomes another way of measuring their distance.", hi: "बिजली, डरे पक्षी, वर्षा से काली धरती और बिछुड़े जोड़े—सब राम के मन में सीता को लौटा लाते हैं। वे सोचते हैं कि कैद में वह भी यही तूफान सुनती होंगी और क्या भय ने उनकी पीड़ा और बढ़ा दी होगी। प्रकृति शोक की सजावट नहीं; उसका हर बदलता संकेत दूरी नापने का नया तरीका बन जाता है।" }, visualCue: "Weather details briefly connect to restrained memory-images of Sita, then return to the live landscape so emotion and geography remain one continuous space.", characterIds: ["rama", "sita", "lakshmana"] },
    { id: "rulers-wait-for-marchable-ground", title: { en: "Even armies obey the season", hi: "सेनाएँ भी ऋतु की सीमा मानती हैं" }, narration: { en: "Rama observes that rulers everywhere suspend campaigns while the rains last. Roads cannot support formations, supply lines or reliable messages, so delay is not unique to him. The recognition does not lessen Sita's danger, but it prevents anguish from producing a doomed expedition that would waste allies before the real search begins.", hi: "राम देखते हैं कि वर्षा रहने तक हर ओर शासक अभियान रोकते हैं। मार्ग सेना की पंक्तियाँ, रसद या भरोसेमंद संदेश नहीं संभाल सकते, इसलिए देर केवल उनकी नहीं है। यह समझ सीता के खतरे को कम नहीं करती, पर पीड़ा को ऐसे असफल अभियान में बदलने से रोकती है जो वास्तविक खोज से पहले सहयोगियों को नष्ट कर देता।" }, visualCue: "Show multiple distant campaign routes paused by the same storm system, making seasonal constraint a world rule instead of an arbitrary local barrier.", characterIds: ["rama", "lakshmana", "sita"] },
    { id: "rama-refuses-an-early-demand", title: { en: "Rama gives Sugriva the promised season", hi: "राम सुग्रीव को वचन वाली ऋतु पूरी देते हैं" }, narration: { en: "Although separation hurts him, Rama will not demand that Sugriva march through impossible ground. He remembers how long Sugriva lived dispossessed and allows his friend the rest that restoration brings. Trust remains conditional on action when autumn opens the roads, but it is not withdrawn merely because waiting is painful.", hi: "वियोग उन्हें घायल करता है, फिर भी राम सुग्रीव से असंभव भूभाग में सेना चलाने की माँग नहीं करते। वे याद रखते हैं कि सुग्रीव कितने समय तक राज्य से वंचित रहे और पुनर्स्थापना के बाद उन्हें विश्राम देते हैं। भरोसा शरद में मार्ग खुलने पर कर्म से जुड़ा है, पर केवल प्रतीक्षा दुखद होने से वापस नहीं लिया जाता।" }, visualCue: "Keep the alliance line intact through the storm, but place a clear autumn action condition on it so patience never reads as an abandoned quest.", characterIds: ["rama", "sugriva", "sita", "lakshmana"] },
  ] } },

  { id: "hanuman-wakes-the-promise", nodeIds: ["hanuman", "sugriva", "nila", "angada", "rama", "kishkindha"], moment: { id: "hanuman-wakes-the-promise", decisiveChange: { en: "Hanuman converts a neglected deadline into mobilization before Rama's anger reaches the city.", hi: "राम का क्रोध नगर पहुँचने से पहले हनुमान छूटी समय-सीमा को सेना जुटाने की कार्रवाई में बदलते हैं।" }, beats: [
    { id: "autumn-arrives-inside-a-pleasured-court", title: { en: "The roads open before the palace notices", hi: "महल के ध्यान देने से पहले मार्ग खुल जाते हैं" }, narration: { en: "The rains end and the campaign season begins, but Sugriva remains absorbed in the pleasures of recovered kingship. Hanuman sees the mismatch before an accusation arrives: Rama's need has not changed, the agreed waiting period has ended, and a ruler who lets comfort obscure time may lose both honour and ally.", hi: "वर्षा समाप्त होती है और अभियान की ऋतु शुरू होती है, पर सुग्रीव पुनः मिले राजसुख में डूबे रहते हैं। आरोप आने से पहले हनुमान असंगति देख लेते हैं—राम की आवश्यकता नहीं बदली, तय प्रतीक्षा पूरी हो चुकी है और आराम में समय भूलने वाला शासक सम्मान तथा मित्र दोनों खो सकता है।" }, visualCue: "Autumn sunlight reaches the reopened road while the palace remains warm and enclosed; Hanuman alone tracks the deadline crossing into overdue time.", characterIds: ["hanuman", "sugriva", "rama"] },
    { id: "hanuman-speaks-as-a-friend-and-minister", title: { en: "Loyal counsel names the uncomfortable duty", hi: "निष्ठावान सलाह असुविधाजनक कर्तव्य का नाम लेती है" }, narration: { en: "Hanuman reminds Sugriva that Rama made kingdom, reputation and reunion possible. Friendship is not preserved by feeling grateful in private; it requires timely repayment when the friend's need becomes actionable. He speaks before fear forces the issue, making correction an act of loyal service rather than courtly rebellion.", hi: "हनुमान सुग्रीव को याद दिलाते हैं कि राम ने राज्य, प्रतिष्ठा और पुनर्मिलन संभव किया। केवल मन में कृतज्ञ होना मित्रता नहीं बचाता; मित्र की आवश्यकता पर समय से उपकार लौटाना पड़ता है। वे भय के मजबूर करने से पहले बोलते हैं, इसलिए सुधार दरबारी विद्रोह नहीं बल्कि निष्ठावान सेवा बनता है।" }, visualCue: "Place Hanuman beside, not beneath, the throne as the promise line brightens between Sugriva and Rama; counsel visibly restores a fading obligation.", characterIds: ["hanuman", "sugriva", "rama"] },
    { id: "sugriva-orders-the-first-mobilization", title: { en: "Sugriva acts before Lakshmana arrives", hi: "लक्ष्मण के आने से पहले सुग्रीव कार्रवाई करते हैं" }, narration: { en: "Sugriva responds by ordering Nila to summon commanders and forces from every direction, with Angada helping inspect and count them. The command sets a strict arrival window and severe consequences for refusal. His delay is real, but so is this first corrective act; the later confrontation will occur while mobilization is already moving beyond sight.", hi: "सुग्रीव नील को हर दिशा से सेनापति और दल बुलाने का आदेश देते हैं तथा अंगद को निरीक्षण और गिनती में साथ लगाते हैं। आदेश आने की कठोर समय-सीमा और अवज्ञा पर गंभीर दंड रखता है। उनकी देर वास्तविक है, पर यह पहला सुधार भी वास्तविक है; बाद का टकराव तब होगा जब तैयारी दृष्टि से परे चल चुकी होगी।" }, visualCue: "Orders radiate from Kishkindha across a world map before any Lakshmana marker leaves Prasravana, preserving the exact sequence of cause and response.", characterIds: ["sugriva", "nila", "angada", "hanuman"] },
    { id: "the-command-leaves-the-palace", title: { en: "A promise becomes messengers and deadlines", hi: "वचन दूतों और समय-सीमाओं में बदलता है" }, narration: { en: "Nila and Angada begin turning the royal order into movement: routes are assigned, distant leaders are called and arriving forces must be counted. Sugriva then returns inside, leaving a dangerous visibility gap. Rama cannot see the work, and a command issued is not yet a completed search, so mistrust can still grow between action and proof.", hi: "नील और अंगद राजादेश को गति में बदलते हैं—मार्ग बाँटे जाते हैं, दूर के नायक बुलाए जाते हैं और आने वाले दल गिने जाने हैं। सुग्रीव फिर भीतर लौटते हैं, जिससे खतरनाक दृश्य-अंतर रह जाता है। राम यह काम देख नहीं सकते और आदेश देना खोज पूरी करना नहीं है, इसलिए कार्रवाई और प्रमाण के बीच अविश्वास बढ़ सकता है।" }, visualCue: "Courier lights leave the city while the palace doors close; retain a fog-of-war boundary that explains why Rama receives no visible confirmation yet.", characterIds: ["nila", "angada", "sugriva", "rama", "hanuman"] },
  ] } },

  { id: "autumn-reopens-rama-grief", nodeIds: ["rama", "lakshmana", "sita", "sugriva", "vali", "prasravana", "kishkindha"], moment: { id: "autumn-reopens-rama-grief", decisiveChange: { en: "Clear weather removes Rama's last reason to wait, while invisible mobilization makes Sugriva appear faithless.", hi: "साफ मौसम राम के पास प्रतीक्षा का अंतिम कारण भी नहीं छोड़ता, और अदृश्य तैयारी सुग्रीव को वचनहीन दिखाती है।" }, beats: [
    { id: "autumn-makes-the-world-passable", title: { en: "The same land becomes a road again", hi: "वही धरती फिर मार्ग बन जाती है" }, narration: { en: "Clouds lift, rivers settle, fields brighten and firm roads return beneath the brothers' feet. The seasonal condition Rama accepted has now ended. What was impossible during rain is possible again, so each clear horizon becomes evidence that waiting must give way to organized movement toward Sita.", hi: "बादल हटते हैं, नदियाँ शांत होती हैं, खेत चमकते हैं और भाइयों के पैरों तले मजबूत मार्ग लौट आते हैं। राम ने जो ऋतु-सीमा मानी थी वह अब समाप्त है। वर्षा में असंभव काम फिर संभव है, इसलिए हर साफ क्षितिज बताता है कि प्रतीक्षा को अब सीता की ओर संगठित गति में बदलना चाहिए।" }, visualCue: "Reverse the flooded-route transformation: roads re-emerge in depth and the autumn action marker unlocks with no artificial barrier remaining.", characterIds: ["rama", "lakshmana", "sita"] },
    { id: "beauty-deepens-rama-separation", title: { en: "Clear skies make absence harder to bear", hi: "साफ आकाश अनुपस्थिति को और कठिन बनाता है" }, narration: { en: "Autumn's birds, moonlight, flowering banks and moving travellers do not console Rama. They remind him that others can reunite and journeys can resume while Sita remains beyond reach. Seasonal beauty sharpens urgency because the world now offers motion, yet no visible ally has arrived at Prasravana to begin it.", hi: "शरद के पक्षी, चाँदनी, फूलों वाले तट और चलते यात्री राम को सांत्वना नहीं देते। वे याद दिलाते हैं कि दूसरे मिल सकते और यात्राएँ फिर शुरू हो सकती हैं, जबकि सीता अब भी पहुँच से बाहर हैं। ऋतु की सुंदरता उतावली बढ़ाती है, क्योंकि संसार गति दे रहा है पर प्रस्रवण पर कोई दृश्य सहयोगी नहीं आया।" }, visualCue: "Let travellers and paired wildlife move through reopened space while Rama remains fixed beside an empty mustering ground and an unresolved Sita direction.", characterIds: ["rama", "sita", "lakshmana", "sugriva"] },
    { id: "rama-sees-no-sign-of-preparation", title: { en: "Hidden work looks exactly like neglect", hi: "छिपी तैयारी उपेक्षा जैसी ही दिखती है" }, narration: { en: "Rama has not heard Sugriva's orders or seen Nila's couriers. From the cave, the promised friend appears to enjoy power while offering no search party, message or timetable. The conclusion is incomplete, but it is understandable from his evidence: the beneficiary is visible in comfort and the rescuer remains alone with loss.", hi: "राम ने सुग्रीव के आदेश नहीं सुने और न नील के दूत देखे। गुफा से वचनबद्ध मित्र सत्ता का आनंद लेते दिखते हैं, पर खोज-दल, संदेश या समय-सारणी कुछ नहीं पहुँचता। उनका निष्कर्ष अधूरा है, फिर भी उपलब्ध प्रमाण से समझ आता है—लाभ पाने वाला सुख में दिखता है और उद्धार चाहने वाला हानि के साथ अकेला।" }, visualCue: "Use split visibility: mobilization moves beyond Rama's fog-of-war while his local view shows only an empty route and distant celebration lights.", characterIds: ["rama", "sugriva", "nila", "sita"] },
    { id: "the-message-inherits-ramas-pain", title: { en: "Rama sends a warning stronger than a reminder", hi: "राम स्मरण से अधिक कठोर चेतावनी भेजते हैं" }, narration: { en: "Rama tells Lakshmana to demand the promised help and invokes Vali's fate if Sugriva has abandoned truth. Grief turns the message into a threat against friend and kingdom. The words reveal how helpless waiting can distort judgment, even though Rama's central claim remains valid: restored power now owes visible action for Sita.", hi: "राम लक्ष्मण से वचन वाली सहायता माँगने को कहते और यदि सुग्रीव ने सत्य छोड़ दिया हो तो वाली के परिणाम की याद दिलाते हैं। शोक संदेश को मित्र और राज्य के विरुद्ध धमकी बना देता है। शब्द दिखाते हैं कि असहाय प्रतीक्षा निर्णय को कैसे तीखा कर सकती है, यद्यपि मूल माँग सही है—पुनः मिली सत्ता अब सीता के लिए दृश्य कार्रवाई की ऋणी है।" }, visualCue: "The message leaves Rama as a red-edged route toward Kishkindha, carrying both a legitimate promise token and a visibly dangerous threat marker.", characterIds: ["rama", "lakshmana", "sugriva", "vali", "sita"] },
  ] } },

  { id: "lakshmana-carries-anger-to-kishkindha", nodeIds: ["lakshmana", "rama", "sugriva", "angada", "tara", "hanuman", "kishkindha"], moment: { id: "lakshmana-carries-anger-to-kishkindha", decisiveChange: { en: "Rama stops Lakshmana from killing a friend, but the messenger's remaining fury still turns Kishkindha into a frightened city.", hi: "राम लक्ष्मण को मित्र की हत्या से रोकते हैं, पर संदेशवाहक का बचा क्रोध फिर भी किष्किंधा को भयभीत नगर बना देता है।" }, beats: [
    { id: "lakshmana-wants-punishment-not-reminder", title: { en: "Lakshmana's anger outruns Rama's command", hi: "लक्ष्मण का क्रोध राम की आज्ञा से आगे निकलता है" }, narration: { en: "Hearing Rama's pain, Lakshmana declares that Sugriva should die and Angada can inherit while others search for Sita. He turns a demand for accountability into immediate replacement and execution. His loyalty to Rama is fierce, but loyalty without restraint is about to create a second crisis beside the first.", hi: "राम की पीड़ा सुनकर लक्ष्मण कहते हैं कि सुग्रीव को मरना चाहिए, अंगद राज्य सँभाल सकते हैं और दूसरे सीता को खोजेंगे। वे जवाबदेही की माँग को तत्काल हत्या और सत्ता-परिवर्तन में बदल देते हैं। राम के प्रति उनकी निष्ठा प्रचंड है, पर संयमहीन निष्ठा पहले संकट के साथ दूसरा संकट खड़ा करने वाली है।" }, visualCue: "Lakshmana's route branches toward lethal confrontation until Rama physically and verbally closes that branch, leaving negotiation as the only valid path.", characterIds: ["lakshmana", "rama", "sugriva", "angada", "sita"] },
    { id: "rama-forbids-killing-a-friend", title: { en: "Rama narrows the mission back to speech", hi: "राम अभियान को फिर संवाद तक सीमित करते हैं" }, narration: { en: "Rama tells Lakshmana not to kill a friend and asks him to restrain anger, use conciliatory words and remind Sugriva of the season. The correction matters: Rama's own warning was violent, yet he refuses to let it become an execution order. The purpose is still to recover cooperation, not win another throne through blood.", hi: "राम लक्ष्मण से कहते हैं कि मित्र की हत्या न करें, क्रोध रोकें, शांत शब्द बोलें और सुग्रीव को ऋतु की याद दिलाएँ। यह सुधार महत्वपूर्ण है—राम की अपनी चेतावनी हिंसक थी, फिर भी वे उसे हत्या का आदेश नहीं बनने देते। उद्देश्य सहयोग वापस पाना है, रक्त से एक और सिंहासन जीतना नहीं।" }, visualCue: "Replace the weapon objective with a spoken-reminder objective while keeping a volatile anger gauge visible; restraint is active work, not instant calm.", characterIds: ["rama", "lakshmana", "sugriva"] },
    { id: "the-approach-terrifies-the-city", title: { en: "Restraint does not yet look gentle", hi: "संयम अभी कोमल नहीं दिखता" }, narration: { en: "Lakshmana strides toward Kishkindha breaking trees and casting rocks aside. Vanaras at the gate see his bow and prepare stones and trunks for defence; families and guards read his arrival as an attack. No blow has landed, but intimidation has already widened a private breach into public fear across the city.", hi: "लक्ष्मण किष्किंधा की ओर बढ़ते हुए पेड़ गिराते और चट्टानें हटाते हैं। द्वार के वानर उनका धनुष देखकर पत्थर और तने रक्षा के लिए उठा लेते हैं; परिवार और प्रहरी आगमन को आक्रमण समझते हैं। प्रहार नहीं हुआ, फिर भी भय ने निजी दरार को नगरव्यापी संकट बना दिया है।" }, visualCue: "Camera depth compresses as Lakshmana advances and civilian routes retreat inward; defensive nodes activate without beginning combat, preserving the near-disaster.", characterIds: ["lakshmana", "kishkindha-vanaras", "sugriva"] },
    { id: "angada-carries-the-demand-inside", title: { en: "Angada becomes the first bridge", hi: "अंगद पहला सेतु बनते हैं" }, narration: { en: "Lakshmana stops at the gate and sends Angada to announce that he waits outside for the promise to be fulfilled. Angada passes through frightened streets to Sugriva, Tara and the ministers. The message finally enters without an arrow, giving the court a narrow chance to wake the king, understand the anger and answer before force returns.", hi: "लक्ष्मण द्वार पर रुककर अंगद को भेजते हैं कि वे बाहर वचन पूरा होने की प्रतीक्षा कर रहे हैं। अंगद भयभीत गलियों से होकर सुग्रीव, तारा और मंत्रियों तक पहुँचते हैं। संदेश अंततः बाण के बिना भीतर जाता है और दरबार को राजा जगाने, क्रोध समझने तथा बल लौटने से पहले उत्तर देने का छोटा अवसर मिलता है।" }, visualCue: "Angada's messenger path passes safely through the defensive perimeter and links gate to inner court, becoming the first nonviolent route across the breach.", characterIds: ["angada", "lakshmana", "sugriva", "tara", "hanuman"] },
  ] } },

  { id: "hanuman-names-the-delay", nodeIds: ["sugriva", "hanuman", "lakshmana", "rama", "kishkindha"], moment: { id: "hanuman-names-the-delay", decisiveChange: { en: "Hanuman refuses both denial and panic, giving Sugriva a truthful path from failure back to duty.", hi: "हनुमान न इंकार चुनते हैं न घबराहट; वे सुग्रीव को चूक से कर्तव्य तक लौटने का सच्चा मार्ग देते हैं।" }, beats: [
    { id: "sugriva-wakes-to-a-crisis-he-cannot-name", title: { en: "The king asks what he has done", hi: "राजा पूछते हैं कि उनसे क्या हुआ" }, narration: { en: "Angada and the ministers wake Sugriva from intoxicated sleep. He says he has spoken no insult and committed no deliberate injury against Rama, so he cannot understand the fury at his gate. His confusion is partly sincere and partly the blindness of comfort: neglect can damage a friend without requiring a hostile sentence or conscious betrayal.", hi: "अंगद और मंत्री सुग्रीव को मदभरी नींद से जगाते हैं। वे कहते हैं कि उन्होंने राम का अपमान नहीं किया और जानबूझकर कोई हानि नहीं पहुँचाई, इसलिए द्वार पर इतना क्रोध समझ नहीं आता। उनका भ्रम कुछ सच्चा और कुछ सुख का अंधापन है—उपेक्षा बिना शत्रुतापूर्ण शब्द या जानबूझकर विश्वासघात के भी मित्र को चोट पहुँचा सकती है।" }, visualCue: "The court's calm state collapses into alarm while the unresolved promise, rather than any insulting message, becomes the highlighted cause of the crisis.", characterIds: ["sugriva", "angada", "rama", "lakshmana"] },
    { id: "hanuman-states-the-missed-season", title: { en: "Hanuman says the deadline was missed", hi: "हनुमान कहते हैं कि समय-सीमा चूक गई" }, narration: { en: "Hanuman answers without flattering the throne: the rainy months are over, Rama waited as agreed, and Sugriva let pleasure consume the moment for action. He also remembers that Rama restored the very life now being enjoyed. The counsel separates malicious betrayal from a serious lapse without using the first distinction to excuse the second.", hi: "हनुमान सिंहासन की चापलूसी किए बिना उत्तर देते हैं—वर्षा समाप्त है, राम ने तय समय तक प्रतीक्षा की और सुग्रीव ने सुख में कर्म का क्षण खो दिया। वे यह भी याद दिलाते हैं कि जिस जीवन का आनंद लिया जा रहा है वही राम ने लौटाया था। सलाह दुर्भावनापूर्ण विश्वासघात और गंभीर चूक को अलग रखती है, पर पहले अंतर से दूसरी गलती को नहीं ढकती।" }, visualCue: "A seasonal timeline, the restored kingdom, and the overdue rescue promise align around Sugriva so the lapse becomes undeniable without branding him an enemy.", characterIds: ["hanuman", "sugriva", "rama"] },
    { id: "receive-the-anger-without-answering-in-kind", title: { en: "Accountability begins by surviving the rebuke", hi: "जवाबदेही कठोर वचन सहने से शुरू होती है" }, narration: { en: "Hanuman advises Sugriva to meet Lakshmana, bow, hear even harsh language patiently and avoid answering anger with royal pride. The goal is not humiliation; it is to keep one frightened encounter from destroying the alliance needed for Sita. A king must absorb some heat when his own delay helped produce it.", hi: "हनुमान सुग्रीव को सलाह देते हैं कि लक्ष्मण से मिलें, झुकें, कठोर भाषा भी धैर्य से सुनें और राज-अभिमान से क्रोध का उत्तर न दें। उद्देश्य अपमान नहीं; भयभीत मुठभेड़ को सीता की खोज वाली मित्रता नष्ट करने से रोकना है। अपनी देर से पैदा ताप का कुछ भाग राजा को स्वयं सहना होगा।" }, visualCue: "Offer Sugriva a de-escalation route through the court: dismiss defensive postures, lower the throne position, and open a direct path to Lakshmana.", characterIds: ["hanuman", "sugriva", "lakshmana", "sita"] },
    { id: "fulfilment-must-follow-apology", title: { en: "Words can reopen the door; action must cross it", hi: "शब्द द्वार खोल सकते हैं; कर्म को उससे गुजरना होगा" }, narration: { en: "Hanuman's final counsel is practical: acknowledge what Rama did, explain without evasion and complete the promised search. An apology without mobilization would leave the underlying wrong untouched. Sugriva already has couriers moving, so he can meet Lakshmana with both humility and evidence that correction has begun.", hi: "हनुमान की अंतिम सलाह व्यावहारिक है—राम के उपकार को स्वीकारें, बिना बचाव के स्थिति बताएँ और वचन वाली खोज पूरी करें। सेना जुटाए बिना क्षमा माँगना मूल गलती को नहीं बदलता। सुग्रीव के दूत पहले से चल रहे हैं, इसलिए वे लक्ष्मण के सामने विनम्रता और शुरू हुए सुधार का प्रमाण दोनों रख सकते हैं।" }, visualCue: "Join the apology path to the active courier network; reconciliation can unlock only when speech and measurable preparation are both present.", characterIds: ["hanuman", "sugriva", "rama", "lakshmana"] },
  ] } },

  { id: "tara-meets-anger-at-the-inner-gate", nodeIds: ["tara", "lakshmana", "sugriva", "angada", "rama", "kishkindha"], moment: { id: "tara-meets-anger-at-the-inner-gate", decisiveChange: { en: "Tara meets Lakshmana between armed anger and a vulnerable court, then supplies the missing fact that mobilization has already begun.", hi: "तारा सशस्त्र क्रोध और असुरक्षित दरबार के बीच लक्ष्मण से मिलती हैं और छूटा तथ्य देती हैं कि सेना जुटना पहले ही शुरू हो चुका है।" }, beats: [
    { id: "lakshmana-crosses-a-restored-city", title: { en: "Prosperity looks like evidence against Sugriva", hi: "समृद्धि सुग्रीव के विरुद्ध प्रमाण जैसी लगती है" }, narration: { en: "Lakshmana enters Kishkindha past gardens, streams, crowded homes and the houses of celebrated commanders. The city's abundance shows how completely Sugriva's fortunes changed through Rama's help. To a messenger arriving from Rama's bare cave, every comfort intensifies the charge that the restored king has enjoyed repayment without returning it.", hi: "लक्ष्मण बागों, धाराओं, भरे घरों और प्रसिद्ध सेनापतियों के निवासों के बीच से किष्किंधा में प्रवेश करते हैं। नगर की समृद्धि दिखाती है कि राम की सहायता से सुग्रीव का भाग्य कितना बदल गया। राम की सूनी गुफा से आए संदेशवाहक को हर सुख यह आरोप और तीखा करता है कि राजा ने उपकार का फल लिया, लौटाया नहीं।" }, visualCue: "Keep Prasravana's sparse cave as a faint comparison layer while Lakshmana moves through rich streets, letting unequal visible outcomes drive his anger.", characterIds: ["lakshmana", "sugriva", "rama", "kishkindha-vanaras"] },
    { id: "the-bowstring-enters-before-words", title: { en: "A bowstring announces the danger", hi: "शब्दों से पहले धनुष की टंकार पहुँचती है" }, narration: { en: "At the inner apartments, music and celebration make Lakshmana ashamed of entering private space and furious at the apparent neglect. He stops short, but releases a thunderous bowstring sound that travels through the palace. Sugriva understands that Angada's warning has arrived in person, and fear reaches the throne before any accusation does.", hi: "अंतरमहल के पास संगीत और उत्सव देखकर लक्ष्मण निजी स्थान में आने से संकोच और दिखती उपेक्षा पर क्रोध दोनों महसूस करते हैं। वे रुकते हैं, पर धनुष की ऐसी टंकार करते हैं जो पूरे महल में फैलती है। सुग्रीव समझ जाते हैं कि अंगद की चेतावनी स्वयं आ पहुँची है और आरोप से पहले भय सिंहासन तक पहुँचता है।" }, visualCue: "Send a visible sound wave through seven palace thresholds; doors pause, music falls away, and the court reorients toward the armed presence outside.", characterIds: ["lakshmana", "sugriva", "angada", "tara"] },
    { id: "tara-opens-a-human-conversation", title: { en: "Tara asks anger to explain itself", hi: "तारा क्रोध से उसका कारण पूछती हैं" }, narration: { en: "Sugriva asks Tara to meet Lakshmana first. She approaches without weapons and asks who has failed him and why the prince burns like fire. Lakshmana answers that Sugriva has lost duty and friendship in pleasure while Rama suffers. By making the accusation speak, Tara moves the encounter away from threat and toward facts that can be tested.", hi: "सुग्रीव तारा से पहले लक्ष्मण से मिलने को कहते हैं। वे बिना शस्त्र पास जाकर पूछती हैं कि किसने आज्ञा नहीं मानी और राजकुमार अग्नि जैसे क्यों जल रहे हैं। लक्ष्मण कहते हैं कि राम दुखी हैं और सुग्रीव सुख में कर्तव्य तथा मित्रता भूल गए। आरोप को बोलने पर मजबूर करके तारा मुठभेड़ को धमकी से जाँच योग्य तथ्यों की ओर मोड़ती हैं।" }, visualCue: "Tara creates a neutral conversational zone between Lakshmana and the inner doors; weapon indicators dim while dialogue choices and evidence routes appear.", characterIds: ["tara", "lakshmana", "sugriva", "rama"] },
    { id: "the-first-missing-fact-reaches-lakshmana", title: { en: "The summons went out before he arrived", hi: "उनके आने से पहले बुलावा जा चुका था" }, narration: { en: "Tara admits that Sugriva was overtaken by recovered pleasure, but tells Lakshmana that orders for Rama's work have already gone out and enormous forces are arriving. This does not erase the missed moment or excuse silence. It changes the question from whether Sugriva will act to whether delayed action can still repair trust in time.", hi: "तारा मानती हैं कि पुनः मिले सुख ने सुग्रीव को बाँध लिया था, पर बताती हैं कि राम के काम के आदेश पहले ही निकल चुके हैं और विशाल दल आ रहे हैं। यह चूका समय या मौन नहीं मिटाता। अब प्रश्न यह नहीं कि सुग्रीव काम करेंगे या नहीं, बल्कि यह है कि देर से शुरू काम समय पर भरोसा सुधार सकता है या नहीं।" }, visualCue: "Reveal courier and incoming-force trails behind Tara's words, lifting part of Lakshmana's fog-of-war without marking the promise completed.", characterIds: ["tara", "lakshmana", "sugriva", "rama", "nila", "angada"] },
  ] } },

  { id: "lakshmana-delivers-the-vali-warning", nodeIds: ["lakshmana", "sugriva", "rama", "vali", "sita", "kishkindha"], moment: { id: "lakshmana-delivers-the-vali-warning", decisiveChange: { en: "Sugriva stands to receive Lakshmana, but the charge of ingratitude still reaches its most dangerous form before repair can begin.", hi: "सुग्रीव लक्ष्मण का सामना करने उठते हैं, पर सुधार शुरू होने से पहले कृतघ्नता का आरोप अपने सबसे खतरनाक रूप में पहुँचता है।" }, beats: [
    { id: "sugriva-rises-with-folded-hands", title: { en: "The king leaves the ease of his seat", hi: "राजा अपने सुखासन से उठते हैं" }, narration: { en: "When Lakshmana enters, Sugriva rises from his golden seat and stands with folded hands. He does not hide behind guards, rank or the private court. The posture follows Hanuman's counsel and opens space for accountability, but it cannot control what the grieving messenger has carried from Rama's cave.", hi: "लक्ष्मण के भीतर आते ही सुग्रीव स्वर्णासन छोड़कर हाथ जोड़कर खड़े होते हैं। वे प्रहरी, पद या निजी दरबार के पीछे नहीं छिपते। यह मुद्रा हनुमान की सलाह मानकर जवाबदेही का स्थान खोलती है, पर राम की गुफा से आए शोकभरे संदेश पर उसका नियंत्रण नहीं है।" }, visualCue: "Lower Sugriva from the elevated throne plane to Lakshmana's level while guards and attendants remain inactive around the tense central line.", characterIds: ["sugriva", "lakshmana", "hanuman"] },
    { id: "lakshmana-builds-the-case-of-ingratitude", title: { en: "The accusation becomes moral judgment", hi: "आरोप नैतिक निर्णय बन जाता है" }, narration: { en: "Lakshmana contrasts a grateful, truthful ruler with one who gains help and refuses to return it. He names Rama's intervention, Sugriva's restored kingdom and the still-unanswered need to find Sita. The argument has force because reciprocity is real, yet it treats incomplete knowledge of mobilization as proof of deliberate falsehood.", hi: "लक्ष्मण कृतज्ञ और सत्यनिष्ठ राजा की तुलना उस शासक से करते हैं जो सहायता लेकर उसे लौटाता नहीं। वे राम का हस्तक्षेप, सुग्रीव का लौटाया राज्य और सीता की अब तक अनुत्तरित खोज गिनाते हैं। पारस्परिक ऋण के कारण तर्क मजबूत है, पर वह सेना जुटने की अधूरी जानकारी को जानबूझकर बोले झूठ का प्रमाण मान लेता है।" }, visualCue: "Lay out the alliance exchange as visible tokens—kingdom restored, promise owed, Sita unfound—while flagging the mobilization evidence as not yet heard.", characterIds: ["lakshmana", "sugriva", "rama", "sita"] },
    { id: "vali-road-enters-the-room", title: { en: "The warning invokes the last king's death", hi: "चेतावनी पिछले राजा की मृत्यु बुलाती है" }, narration: { en: "Lakshmana repeats that the road Vali travelled has not closed and that Rama's arrows can send Sugriva along it. The words bring the previous violent transfer of power into the room as a threat against the new ruler. Accountability now stands dangerously close to coercion by remembered killing.", hi: "लक्ष्मण दोहराते हैं कि वाली जिस राह गए वह बंद नहीं हुई और राम के बाण सुग्रीव को भी उसी पर भेज सकते हैं। शब्द सत्ता के पिछले हिंसक परिवर्तन को नए राजा के विरुद्ध धमकी बनाकर कक्ष में ले आते हैं। जवाबदेही अब पिछली हत्या के भय से कराई जा रही आज्ञाकारिता के बहुत पास खड़ी है।" }, visualCue: "A shadow route from Vali's death briefly overlays Sugriva's position; keep it visibly marked as a threat, not as a completed or approved action.", characterIds: ["lakshmana", "sugriva", "rama", "vali"] },
    { id: "the-court-holds-before-the-answer", title: { en: "No one answers violence with violence", hi: "हिंसा का उत्तर हिंसा से नहीं दिया जाता" }, narration: { en: "Sugriva remains standing rather than reaching for force, and the surrounding court does not attack Lakshmana. That pause preserves the possibility Tara and Hanuman created. The accusation has been delivered in full; the next task is to separate lapse from betrayal, show what has already moved and restore the alliance without pretending the threat was harmless.", hi: "सुग्रीव बल उठाने के बजाय खड़े रहते हैं और आसपास का दरबार लक्ष्मण पर आक्रमण नहीं करता। यह विराम तारा और हनुमान की बनाई संभावना बचाता है। पूरा आरोप सामने आ चुका है; अब चूक को विश्वासघात से अलग करना, शुरू तैयारी दिखाना और धमकी को निर्दोष माने बिना मित्रता सुधारना है।" }, visualCue: "Freeze combat affordances for one charged beat while Tara's evidence route and Sugriva's response route remain open as the only forward paths.", characterIds: ["sugriva", "lakshmana", "tara", "hanuman"] },
  ] } },

  { id: "tara-reveals-the-mobilization", nodeIds: ["tara", "lakshmana", "sugriva", "rama", "sita", "vali", "kishkindha"], moment: { id: "tara-reveals-the-mobilization", decisiveChange: { en: "Tara defends Sugriva without denying his lapse and replaces Lakshmana's assumption of inaction with evidence of an army already moving.", hi: "तारा सुग्रीव की चूक नकारे बिना उनका पक्ष रखती हैं और लक्ष्मण की निष्क्रियता वाली धारणा के सामने चलती सेना का प्रमाण देती हैं।" }, beats: [
    { id: "tara-rejects-the-word-ungrateful", title: { en: "Tara disputes betrayal, not responsibility", hi: "तारा विश्वासघात नकारती हैं, जिम्मेदारी नहीं" }, narration: { en: "Tara tells Lakshmana that Sugriva is neither heartless nor false and has not forgotten what Rama did. She does not claim that his conduct was timely. Her defence draws a necessary boundary: being overcome by comfort after long deprivation is a serious failure of attention, but it is not the same as deciding to abandon a friend.", hi: "तारा लक्ष्मण से कहती हैं कि सुग्रीव न हृदयहीन हैं, न झूठे, और राम का उपकार भूले नहीं। वे यह दावा नहीं करतीं कि उनका आचरण समय पर था। उनका पक्ष जरूरी सीमा खींचता है—लंबे अभाव के बाद सुख में डूबकर ध्यान चूकना गंभीर गलती है, पर मित्र को छोड़ देने का निर्णय उससे अलग है।" }, visualCue: "Separate two status markers over Sugriva—missed duty confirmed, deliberate betrayal unproven—so accountability survives without flattening motive.", characterIds: ["tara", "lakshmana", "sugriva", "rama"] },
    { id: "pleasure-explains-but-does-not-erase", title: { en: "An explanation is not an acquittal", hi: "कारण बताना दोष मिटाना नहीं" }, narration: { en: "Tara describes how recovered intimacy and kingship distorted Sugriva's sense of passing time. She asks Lakshmana to examine the whole situation before giving anger control. The explanation makes the lapse intelligible, not acceptable; Rama still waited through every agreed month and deserved communication when the season turned.", hi: "तारा बताती हैं कि पुनः मिले संबंध और राजसुख ने सुग्रीव की समय-बोध को कैसे बिगाड़ा। वे लक्ष्मण से क्रोध को नियंत्रण देने से पहले पूरी स्थिति देखने को कहती हैं। कारण चूक को समझने योग्य बनाता है, उचित नहीं; राम ने तय हर महीना प्रतीक्षा की और ऋतु बदलते ही संदेश पाने के अधिकारी थे।" }, visualCue: "Run the shared seasonal timeline through both Prasravana and palace states, showing the same elapsed months experienced as grief in one place and comfort in another.", characterIds: ["tara", "lakshmana", "sugriva", "rama"] },
    { id: "the-search-needs-a-coalition", title: { en: "Ravana cannot be pursued by outrage alone", hi: "केवल क्रोध से रावण का पीछा नहीं हो सकता" }, narration: { en: "Tara says the enemy commands vast, mobile forces and that Rama needs allies who know forests, mountains and strongholds. Vali had spoken of that scale before his death. Her point is operational: recovering Sita requires intelligence and reach, not only the strength of one bow, so preparation itself is part of rescue.", hi: "तारा कहती हैं कि शत्रु के पास विशाल, रूप बदलने वाली शक्ति है और राम को ऐसे सहयोगी चाहिए जो वन, पर्वत और दुर्ग जानते हों। वाली ने मृत्यु से पहले इस विस्तार का उल्लेख किया था। बात व्यावहारिक है—सीता की वापसी के लिए सूचना और पहुँच चाहिए, केवल एक धनुष की शक्ति नहीं; तैयारी भी बचाव का भाग है।" }, visualCue: "Expand from the palace to layered terrains and an unknown Ravana reach, illustrating why a distributed coalition is necessary without inventing his precise location.", characterIds: ["tara", "lakshmana", "rama", "sita", "ravana", "vali"] },
    { id: "incoming-forces-answer-the-charge", title: { en: "The roads already carry an answer", hi: "मार्ग पहले से उत्तर लेकर आ रहे हैं" }, narration: { en: "Tara reveals that commanders were sent to summon the host and that bears, vanaras and other contingents are converging that very day. Lakshmana can now test her words against arrivals rather than trust a promise alone. The disclosure does not complete the search, but it transforms the court from a place of indulgence into the center of a delayed mobilization.", hi: "तारा बताती हैं कि सेनापतियों को दल बुलाने भेजा गया और भालू, वानर तथा अन्य टुकड़ियाँ उसी दिन जुट रही हैं। अब लक्ष्मण केवल वचन पर भरोसा करने के बजाय आते दलों से बात जाँच सकते हैं। खुलासा खोज पूरी नहीं करता, पर दरबार को विलास के स्थान से देर से चल रही तैयारी के केंद्र में बदल देता है।" }, visualCue: "Incoming formations begin appearing on every edge of the Kishkindha map, replacing the blank evidence field with verifiable movement while the search remains locked.", characterIds: ["tara", "lakshmana", "sugriva", "rama", "vanara-forces"] },
  ] } },

  { id: "friends-repair-the-breach", nodeIds: ["sugriva", "lakshmana", "rama", "sita", "ravana", "kishkindha"], moment: { id: "friends-repair-the-breach", decisiveChange: { en: "Sugriva and Lakshmana each acknowledge what they owe, turning a near-violent breach back into shared action for Sita.", hi: "सुग्रीव और लक्ष्मण दोनों अपना दायित्व स्वीकारते हैं और लगभग हिंसक दरार को फिर सीता के लिए साझा कर्म में बदलते हैं।" }, beats: [
    { id: "sugriva-credits-the-restoration", title: { en: "Sugriva names what Rama gave him", hi: "सुग्रीव राम से मिला सब कुछ गिनाते हैं" }, narration: { en: "Sugriva says that kingdom, reputation and recovered fortune came through Rama. He does not claim that issuing orders makes the debt disappear. By naming the imbalance openly, he meets Lakshmana's central moral charge and places his royal power back inside the friendship that made its recovery possible.", hi: "सुग्रीव कहते हैं कि राज्य, प्रतिष्ठा और लौटा सौभाग्य राम के कारण मिला। वे यह दावा नहीं करते कि आदेश जारी होते ही ऋण समाप्त हो गया। असमानता को खुलकर मानकर वे लक्ष्मण के मूल नैतिक आरोप का उत्तर देते और अपनी राजसत्ता को उसी मित्रता के भीतर रखते हैं जिसने उसकी वापसी संभव की।" }, visualCue: "Restoration tokens move from Sugriva's throne back onto the alliance line, visually acknowledging origin without stripping him of present responsibility.", characterIds: ["sugriva", "rama", "lakshmana"] },
    { id: "help-is-offered-without-self-importance", title: { en: "The ally promises service, not ownership of victory", hi: "सहयोगी सेवा का वचन देता है, विजय का स्वामित्व नहीं" }, narration: { en: "Sugriva praises Rama's strength and says the gathered forces will support rather than replace it. He will follow when Rama moves against Ravana. The humility avoids turning assistance into a boast, while the promise remains concrete: intelligence, numbers and local knowledge will now be placed behind the effort to recover Sita.", hi: "सुग्रीव राम की शक्ति की प्रशंसा कर कहते हैं कि जुटे दल उसका स्थान नहीं लेंगे, उसे सहारा देंगे। रावण के विरुद्ध राम चलेंगे तो वे साथ चलेंगे। विनम्रता सहायता को डींग नहीं बनने देती, जबकि वचन ठोस है—सीता की खोज में अब सूचना, संख्या और स्थानीय ज्ञान लगाया जाएगा।" }, visualCue: "Position Sugriva's coalition behind a shared Sita objective rather than above Rama, combining complementary capabilities into one forward route.", characterIds: ["sugriva", "rama", "ravana", "sita", "lakshmana"] },
    { id: "sugriva-asks-for-forgiveness", title: { en: "The lapse is admitted without a defence", hi: "चूक बिना बहाने के स्वीकार की जाती है" }, narration: { en: "Sugriva asks Rama to forgive any transgression born from confidence, comfort or familiarity. He does not demand that Tara's explanation cancel the hurt. The request accepts that close friendship can make duty feel safe enough to postpone, and that the harmed friend still deserves acknowledgment even after corrective work has begun.", hi: "सुग्रीव राम से उस चूक की क्षमा माँगते हैं जो भरोसे, आराम या घनिष्ठता से हुई। वे यह नहीं कहते कि तारा का कारण पीड़ा मिटा देता है। निवेदन मानता है कि निकट मित्रता कर्तव्य को इतना सुरक्षित दिखा सकती है कि उसे टाला जाए, और सुधार शुरू होने पर भी घायल मित्र स्वीकारोक्ति का अधिकारी है।" }, visualCue: "Present apology as an explicit relationship repair action connected to, but distinct from, the active mobilization network; neither substitutes for the other.", characterIds: ["sugriva", "rama", "lakshmana", "tara"] },
    { id: "lakshmana-apologises-and-invites-return", title: { en: "Lakshmana also owns his excess", hi: "लक्ष्मण भी अपनी अति स्वीकारते हैं" }, narration: { en: "Lakshmana accepts Sugriva's answer, affirms his worth as Rama's ally and asks forgiveness for the harshness carried from a grieving brother. He then asks Sugriva to come soothe Rama in person. Repair is mutual: delay required correction, but violent speech also required acknowledgment before they could move together.", hi: "लक्ष्मण सुग्रीव का उत्तर स्वीकारते, उन्हें राम का योग्य सहयोगी मानते और दुखी भाई की ओर से लाए कठोर शब्दों के लिए क्षमा माँगते हैं। फिर वे उनसे स्वयं राम को शांत करने चलने को कहते हैं। सुधार दोनों ओर है—देर को ठीक करना था, पर साथ चलने से पहले हिंसक भाषा को भी स्वीकारना था।" }, visualCue: "The red threat edge fades from Lakshmana's route as he and Sugriva form a shared return path to Prasravana, with the search objective ahead.", characterIds: ["lakshmana", "sugriva", "rama", "sita"] },
  ] } },

  { id: "orders-cross-the-world", nodeIds: ["sugriva", "hanuman", "rama", "vanara-couriers", "vanara-forces", "kishkindha", "himalaya", "vindhya", "kailasa"], moment: { id: "orders-cross-the-world", decisiveChange: { en: "Sugriva turns his earlier summons into a worldwide relay, and distant communities begin arriving as a usable search network.", hi: "सुग्रीव पहले बुलावे को विश्वव्यापी संदेश-श्रृंखला बनाते हैं और दूर के समुदाय उपयोगी खोज-जाल के रूप में पहुँचने लगते हैं।" }, beats: [
    { id: "hanuman-receives-the-expanded-order", title: { en: "The summons grows beyond the first command", hi: "बुलावा पहले आदेश से भी व्यापक होता है" }, narration: { en: "Sugriva directs Hanuman to reach communities on Mahendra, Himalaya, Vindhya, Kailasa, western coasts, remote forests, caves and hermitages. The list is not ornamental geography; each region adds travellers adapted to a different terrain. A search for an unknown destination must reach farther than the king's ordinary chain of command.", hi: "सुग्रीव हनुमान को महेंद्र, हिमालय, विंध्य, कैलास, पश्चिमी तटों, दूरस्थ वनों, गुफाओं और आश्रमों के समुदायों तक पहुँचने को कहते हैं। यह केवल भूगोल की सजावटी सूची नहीं; हर क्षेत्र अलग भूभाग में चलने वाले खोजी देता है। अज्ञात गंतव्य की खोज को राजा की सामान्य आदेश-श्रृंखला से कहीं दूर जाना होगा।" }, visualCue: "Unfold a layered world map from Kishkindha and activate distinct terrain regions, each contributing a route capability rather than a decorative label.", characterIds: ["sugriva", "hanuman", "rama"] },
    { id: "fast-couriers-chase-the-first-couriers", title: { en: "Speed is added to an order already moving", hi: "चलते आदेश में और गति जोड़ी जाती है" }, narration: { en: "Sugriva knows the first messengers are swift, but sends more to urge every delayed leader onward. The second wave proves that mobilization did not begin only after Lakshmana's threat; it accelerates work already underway. Correction here means monitoring an order, discovering lag and reinforcing it until distant intent becomes arrival.", hi: "सुग्रीव जानते हैं कि पहले दूत तेज हैं, फिर भी पीछे रह गए हर दलनायक को आगे बढ़ाने के लिए और दूत भेजते हैं। दूसरी लहर साबित करती है कि तैयारी केवल लक्ष्मण की धमकी के बाद शुरू नहीं हुई; वह चल रहे काम को तेज करती है। सुधार का अर्थ आदेश देकर भूलना नहीं, बल्कि देर पहचानकर उसे तब तक मजबूत करना है जब तक दूर का इरादा आगमन न बन जाए।" }, visualCue: "Show second-wave couriers overtaking and reinforcing first-wave routes, with lagging regions changing from pending to moving rather than instantly complete.", characterIds: ["sugriva", "hanuman", "vanara-couriers"] },
    { id: "the-world-answers-in-different-forms", title: { en: "Every landscape sends different strength", hi: "हर भूभाग अलग शक्ति भेजता है" }, narration: { en: "Dark mountain dwellers, golden western bands, Himalayan foragers and coastal communities leave their homes for Kishkindha. Their legendary numbers express the scale of response, while their varied origins matter more than arithmetic. Together they can cross forests, heights, rivers and shores that no single local patrol could cover.", hi: "काले पर्वतीय दल, स्वर्णिम पश्चिमी समूह, हिमालयी वनचारी और तटीय समुदाय अपने घरों से किष्किंधा की ओर निकलते हैं। उनकी विशाल संख्याएँ प्रतिक्रिया का विस्तार बताती हैं, पर गणना से अधिक उनकी विविध उत्पत्ति महत्वपूर्ण है। साथ मिलकर वे वन, ऊँचाई, नदियाँ और तट छान सकते हैं जिन्हें एक स्थानीय दल नहीं देख सकता।" }, visualCue: "Bring contingents in visually distinct terrain-adapted streams, avoiding an unreadable mass while preserving the sensation of a world responding.", characterIds: ["vanara-forces", "hanuman", "sugriva"] },
    { id: "returning-messengers-bring-proof", title: { en: "The order returns as evidence", hi: "आदेश प्रमाण बनकर लौटता है" }, narration: { en: "Couriers return with leaders, healing herbs, fruits and reports that forces across the earth are on their way. Sugriva can now show more than intention: messengers completed routes, supplies moved and contingents crossed real distance. The network is not yet assigned to directions, but the disputed promise has become measurable preparation.", hi: "दूत दलनायकों, औषधियों, फलों और इस समाचार के साथ लौटते हैं कि धरती भर की सेनाएँ आ रही हैं। अब सुग्रीव केवल इरादा नहीं, पूरा मार्ग, चली रसद और पार की वास्तविक दूरी दिखा सकते हैं। दल अभी खोज-दिशाओं में नहीं बाँटे गए, पर विवादित वचन मापी जा सकने वाली तैयारी बन चुका है।" }, visualCue: "Convert returning routes into inspectable arrival records and supplies at Kishkindha, while keeping direction assignments reserved for the next search turn.", characterIds: ["vanara-couriers", "vanara-forces", "sugriva", "hanuman"] },
  ] } },

  { id: "sugriva-returns-to-rama", nodeIds: ["sugriva", "lakshmana", "rama", "hanuman", "vanara-forces", "prasravana", "kishkindha"], moment: { id: "sugriva-returns-to-rama", decisiveChange: { en: "Sugriva leaves palace comfort, returns to Rama in person and makes the delayed promise visible as a gathered coalition.", hi: "सुग्रीव महल का सुख छोड़कर स्वयं राम के पास लौटते हैं और देर हुए वचन को जुटे गठबंधन के रूप में दृश्य बनाते हैं।" }, beats: [
    { id: "sugriva-leaves-the-inner-court", title: { en: "Reconciliation moves out of the palace", hi: "मेल-मिलाप महल से बाहर निकलता है" }, narration: { en: "Sugriva dismisses the private gathering, calls for transport and asks Lakshmana to travel with him. The public departure matters because the crisis began with a ruler apparently hidden in pleasure. He now leaves that protected space under the eyes of attendants and forces, placing his body and kingship on the road back to Rama.", hi: "सुग्रीव निजी सभा विदा करते, वाहन बुलाते और लक्ष्मण से साथ चलने को कहते हैं। सार्वजनिक प्रस्थान महत्वपूर्ण है क्योंकि संकट उस राजा से शुरू हुआ जो सुख में छिपा दिखाई देता था। अब वे सेवकों और सेना के सामने सुरक्षित स्थान छोड़कर स्वयं तथा अपनी राजसत्ता को राम की ओर जाने वाले मार्ग पर रखते हैं।" }, visualCue: "Open the palace depth into the road to Prasravana; Sugriva and Lakshmana travel on one line while celebration spaces close behind them.", characterIds: ["sugriva", "lakshmana", "tara", "hanuman"] },
    { id: "the-king-bows-before-the-friend", title: { en: "Royal display ends in a bow", hi: "राजसी प्रदर्शन झुकने पर समाप्त होता है" }, narration: { en: "Sugriva arrives with royal signs and an armed escort, then steps down and folds his hands before Rama. The surrounding forces follow his gesture. He does not ask Rama to come into Kishkindha or accept court ceremony; he brings the court's capacity to the exiled friend's sparse shelter and acknowledges where the unfinished duty lies.", hi: "सुग्रीव राजचिह्न और सशस्त्र दल के साथ आते हैं, फिर उतरकर राम के सामने हाथ जोड़ते हैं। आसपास की सेना भी उनका अनुसरण करती है। वे राम को किष्किंधा या दरबारी समारोह में नहीं बुलाते; दरबार की क्षमता वनवासी मित्र के साधारण आश्रय तक लाकर स्वीकारते हैं कि अधूरा कर्तव्य कहाँ है।" }, visualCue: "Royal height and ornament descend into Rama's austere ground plane; the assembled host mirrors Sugriva's bow without crowding the two friends.", characterIds: ["sugriva", "rama", "lakshmana", "vanara-forces"] },
    { id: "rama-embraces-before-he-instructs", title: { en: "Relationship is restored before command resumes", hi: "आदेश से पहले संबंध फिर जुड़ता है" }, narration: { en: "Rama raises and embraces Sugriva rather than extending the threat carried earlier. The gesture accepts the repair and recognizes a friend, not merely a subordinate. Only after seating him does Rama speak about balancing duty, prosperity and pleasure, allowing accountability to continue without making shame the permanent basis of cooperation.", hi: "राम पहले वाली धमकी आगे बढ़ाने के बजाय सुग्रीव को उठाकर गले लगाते हैं। यह सुधार स्वीकारकर अधीनस्थ नहीं, मित्र को पहचानता है। बैठाने के बाद ही राम कर्तव्य, समृद्धि और सुख के संतुलन की बात करते हैं, ताकि जवाबदेही चलती रहे पर लज्जा सहयोग का स्थायी आधार न बने।" }, visualCue: "The broken alliance line reconnects at the embrace, then stabilizes into a shared planning table rather than a dominance hierarchy.", characterIds: ["rama", "sugriva", "lakshmana"] },
    { id: "rama-says-the-time-for-effort-has-come", title: { en: "Forgiveness does not extend the delay", hi: "क्षमा देर को आगे नहीं बढ़ाती" }, narration: { en: "Rama says a ruler must give proper time to duty, prosperity and pleasure, and that the season for effort has arrived. Sugriva answers by pointing to leaders already present and countless others still approaching. Friendship is restored, but the standard is now operational: the assembled force must be organized to find Sita and reach Ravana.", hi: "राम कहते हैं कि शासक को कर्तव्य, समृद्धि और सुख को उचित समय देना चाहिए और अब परिश्रम की ऋतु आ गई है। सुग्रीव उपस्थित दलनायकों तथा मार्ग में आ रहे असंख्य समूहों की ओर संकेत करते हैं। मित्रता लौट गई, पर कसौटी अब व्यावहारिक है—सेना को सीता की खोज और रावण तक पहुँचने के लिए व्यवस्थित करना होगा।" }, visualCue: "Unlock the mustering interface at Rama's words; arriving forces become sortable by leader and terrain, but directional search orders remain the next objective.", characterIds: ["rama", "sugriva", "sita", "ravana", "vanara-forces"] },
  ] } },

  { id: "the-horizon-fills-with-allies", nodeIds: ["rama", "sugriva", "hanuman", "angada", "jambavan", "nila", "vanara-leaders", "prasravana", "kishkindha"], moment: { id: "the-horizon-fills-with-allies", decisiveChange: { en: "The repaired friendship becomes a visible, countable host, ready to be divided across the unknown horizons of Sita's search.", hi: "सुधरी मित्रता दृश्य और गिनी जा सकने वाली सेना बनती है, जिसे सीता की खोज के अज्ञात क्षितिजों में बाँटा जा सकेगा।" }, beats: [
    { id: "rama-affirms-the-friendship", title: { en: "Rama recognizes Sugriva as the kind of friend who acts", hi: "राम सुग्रीव को कर्म करने वाला मित्र मानते हैं" }, narration: { en: "Rama compares Sugriva's help to rain, sunlight and moonlight performing their natural work. He says he trusts the ally to speak and act for his good, and places confidence in their combined effort against Ravana. The affirmation closes the personal dispute without claiming that Sita has already been found.", hi: "राम सुग्रीव की सहायता की तुलना वर्षा, सूर्यप्रकाश और चाँदनी के स्वाभाविक काम से करते हैं। वे कहते हैं कि मित्र उनके हित में बोलेगा और कर्म करेगा तथा रावण के विरुद्ध संयुक्त प्रयास पर भरोसा रखते हैं। यह स्वीकृति निजी विवाद बंद करती है, पर सीता मिल गई हैं ऐसा दावा नहीं करती।" }, visualCue: "Stabilize the alliance link at full strength while the Sita location remains intentionally unknown, separating relationship repair from mission completion.", characterIds: ["rama", "sugriva", "sita", "ravana"] },
    { id: "dust-announces-the-host", title: { en: "The ground trembles before the leaders appear", hi: "दलनायकों से पहले धरती उनका समाचार देती है" }, narration: { en: "Dust rises until sunlight dims, the earth trembles and calls roll across the forests. The arriving host is first experienced as weather and vibration, conveying scale before individual faces can be seen. What Rama mistook for absence now fills every approach, turning hidden preparation into an undeniable public fact.", hi: "धूल उठकर सूर्य का प्रकाश मंद करती है, धरती काँपती है और वनों में पुकार फैलती है। आने वाली सेना पहले मौसम और कंपन की तरह महसूस होती है, जिससे अलग चेहरे दिखने से पहले ही विस्तार समझ आता है। जिसे राम ने अनुपस्थिति माना था वह अब हर मार्ग भर देता है और छिपी तैयारी निर्विवाद सार्वजनिक तथ्य बन जाती है।" }, visualCue: "Use layered particles, distant silhouettes and ground response before resolving any crowd detail, preserving performance while making scale physically felt.", characterIds: ["rama", "sugriva", "vanara-leaders", "vanara-forces"] },
    { id: "leaders-emerge-from-the-mass", title: { en: "A crowd becomes a network of known leaders", hi: "भीड़ पहचाने हुए नायकों का जाल बनती है" }, narration: { en: "Satavali, Sushena, Kesari, Gavaksha, Dhumra, Nila, Mainda, Dvivida, Jambavan, Angada, Hanuman and many others report with their own contingents. The scale remains legendary, but leadership gives it structure. Each named group can later receive a direction, terrain and responsibility instead of remaining an unusable sea of bodies.", hi: "शतबलि, सुषेण, केसरी, गवाक्ष, धूम्र, नील, मैन्द, द्विविद, जाम्बवान, अंगद, हनुमान और अनेक अन्य अपने दलों सहित पहुँचते हैं। विस्तार अलौकिक है, पर नेतृत्व उसे संरचना देता है। हर नामित समूह को आगे दिशा, भूभाग और जिम्मेदारी दी जा सकती है; वह अनुपयोगी भीड़ बनकर नहीं रहता।" }, visualCue: "Resolve the vast host into selectable leader constellations with clustered contingents, preventing visual clutter while retaining relational scale.", characterIds: ["satavali", "sushena", "kesari", "gavaksha", "dhumra", "nila", "mainda", "dvivida", "jambavan", "angada", "hanuman"] },
    { id: "the-army-is-counted-before-it-searches", title: { en: "Arrival becomes readiness through organization", hi: "संगठन आगमन को तैयारी बनाता है" }, narration: { en: "Sugriva orders those who understand the host to station forces near streams and forests and determine who has arrived and who is missing. Numbers alone are not readiness. Counting, locating and linking leaders to their contingents creates the command picture needed for the next move: dividing the world into searchable horizons.", hi: "सुग्रीव सेना जानने वालों को दलों को धाराओं और वनों के पास ठहराने तथा यह जाँचने का आदेश देते हैं कि कौन आया और कौन शेष है। केवल संख्या तैयारी नहीं होती। गिनती, स्थान और नायकों को उनके दल से जोड़ना अगली चाल के लिए जरूरी व्यवस्था बनाता है—संसार को खोजी जा सकने वाली दिशाओं में बाँटना।" }, visualCue: "Transition from spectacle to an organized mustering map with leader, location and attendance layers; a four-horizon search control remains visibly next.", characterIds: ["sugriva", "rama", "hanuman", "angada", "jambavan", "nila", "vanara-leaders"] },
  ] } },
];
